package com.sisge.ms.service;
import com.sisge.ms.dto.personal.PersonalAdminDtos; import com.sisge.ms.entity.*; import com.sisge.ms.exception.ApiException; import com.sisge.ms.model.PersonalImportStatus; import com.sisge.ms.repository.*; import com.sisge.ms.security.CurrentUser; import java.math.BigDecimal; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PersonalConsolidationService {
 private final ImportacionPersonalRepository imports; private final ImportacionPersonalFilaRepository rows; private final PersonaRepository people; private final DesignacionRepository designaciones; private final AdicionalRepository adicionales; private final DesignacionAdicionalRepository designacionAdicionales; private final AuditoriaService audit;
 public PersonalConsolidationService(ImportacionPersonalRepository imports,ImportacionPersonalFilaRepository rows,PersonaRepository people,DesignacionRepository designaciones,AdicionalRepository adicionales,DesignacionAdicionalRepository designacionAdicionales,AuditoriaService audit){this.imports=imports;this.rows=rows;this.people=people;this.designaciones=designaciones;this.adicionales=adicionales;this.designacionAdicionales=designacionAdicionales;this.audit=audit;}
 @Transactional(readOnly=true) public PersonalAdminDtos.Validation validate(Long id){ CurrentUser.get().requireGlobal("PERSONAL_APROBAR"); ImportacionPersonal imp=find(id); Counts c=count(imp, false); return new PersonalAdminDtos.Validation(id,c.newPeople,c.oldPeople,c.newDesignations,c.oldDesignations,c.masters,c.invalid,c.invalidAdditional,c.duplicates); }
 @Transactional public PersonalAdminDtos.Consolidation consolidate(Long id){ CurrentUser.get().requireGlobal("PERSONAL_APROBAR"); ImportacionPersonal imp=imports.lockById(id).orElseThrow(()->ApiException.notFound("Personnel importation not found")); if(imp.getEstado()!=PersonalImportStatus.APROBADO) throw ApiException.conflict("Only approved importations can be consolidated"); Counts check=count(imp,false); if(check.invalid>0||check.masters>0||check.invalidAdditional>0) throw ApiException.conflict("Importation has blocking validation errors"); Counts c=new Counts();
  for(ImportacionPersonalFila row:rows.findByImportacionId(id)){ Persona person=findConsistent(row); boolean existed=person.getId()!=null; String oldPerson=personJson(person); copy(person,row); people.save(person); audit.recordChange(imp.getOrganizacion(),existed?"PERSONA_ACTUALIZADA":"PERSONA_CREADA","PERSONA",person.getId(),oldPerson,personJson(person)); if(existed)c.oldPeople++;else c.newPeople++; Designacion d=designaciones.findFirstByPersonaIdAndOrganizacionIdAndSectorIdAndFechaInicio(person.getId(),row.getOrganizacion().getId(),row.getSector()==null?null:row.getSector().getId(),row.getFechaInicio()).orElse(null); boolean dExists=d!=null; String oldDesignacion=designacionJson(d); if(d==null){d=new Designacion();d.setPersona(person);d.setOrganizacion(row.getOrganizacion());d.setSector(row.getSector());} d.setEscalafon(row.getEscalafon());d.setCategoria(row.getCategoria());d.setSituacionRevista(row.getSituacionRevista());d.setAgrupamiento(row.getAgrupamiento());d.setFuncion(row.getFuncion());d.setTipoAfectacion(row.getTipoAfectacion());d.setFechaInicio(row.getFechaInicio());d.setAntiguedadAnios(row.getAntiguedadAnios());d.setAfectado(Boolean.TRUE.equals(row.getAfectado()));designaciones.save(d);audit.recordChange(imp.getOrganizacion(),dExists?"DESIGNACION_ACTUALIZADA":"DESIGNACION_CREADA","DESIGNACION",d.getId(),oldDesignacion,designacionJson(d));if(dExists)c.oldDesignations++;else c.newDesignations++; c.additional += additional(d,row,"ADICIONAL_MH",row.getAdicionalMh(),imp.getOrganizacion())+additional(d,row,"ADICIONAL_JEFATURA",row.getAdicionalJefatura(),imp.getOrganizacion()); audit.record(imp.getOrganizacion(),"CONSOLIDACION","IMPORTACION_PERSONAL_FILA",row.getId()); }
  imp.markConsolidated();audit.record(imp.getOrganizacion(),"CONSOLIDACION","IMPORTACION_PERSONAL",id);return new PersonalAdminDtos.Consolidation(id,c.newPeople,c.oldPeople,c.newDesignations,c.oldDesignations,c.additional,0); }
 private Counts count(ImportacionPersonal imp,boolean ignored){Counts c=new Counts();for(ImportacionPersonalFila r:rows.findByImportacionId(imp.getId())){if(r.getErrores()!=null&&!r.getErrores().isBlank()||r.getDni()==null||r.getDni().isBlank()||r.getOrganizacion()==null){c.invalid++;continue;}if(r.getEscalafon()==null||r.getCategoria()==null||r.getSituacionRevista()==null||r.getAgrupamiento()==null||r.getFuncion()==null)c.masters++;if(!validNumber(r.getAdicionalMh())||!validNumber(r.getAdicionalJefatura()))c.invalidAdditional++;Optional<Persona> p=people.findByDni(r.getDni());if(p.isPresent())c.oldPeople++;else c.newPeople++;if(p.isPresent()&&r.getCuil()!=null&&!r.getCuil().isBlank()&&p.get().getCuil()!=null&&!r.getCuil().equals(p.get().getCuil()))c.duplicates++;if(p.isPresent()&&designaciones.findFirstByPersonaIdAndOrganizacionIdAndSectorIdAndFechaInicio(p.get().getId(),r.getOrganizacion().getId(),r.getSector()==null?null:r.getSector().getId(),r.getFechaInicio()).isPresent())c.oldDesignations++;else c.newDesignations++;}return c;}
 private Persona findConsistent(ImportacionPersonalFila r){Optional<Persona> byDni=people.findByDni(r.getDni());Optional<Persona> byCuil=r.getCuil()==null||r.getCuil().isBlank()?Optional.empty():people.findByCuil(r.getCuil());if(byDni.isPresent()&&byCuil.isPresent()&&!Objects.equals(byDni.get().getId(),byCuil.get().getId()))throw ApiException.conflict("DNI/CUIL inconsistency requires review");return byDni.or(()->byCuil).orElseGet(Persona::new);}
 private void copy(Persona p,ImportacionPersonalFila r){p.setDni(r.getDni());p.setCuil(r.getCuil()==null||r.getCuil().isBlank()?null:r.getCuil());p.setNombres(r.getNombres());p.setApellido(r.getApellido());p.setSexo(r.getSexo());p.setFechaNacimiento(r.getFechaNacimiento());}
 private int additional(Designacion d,ImportacionPersonalFila row,String code,String source,Organizacion org){if(source==null||source.isBlank())return 0;Adicional a=adicionales.findByCodigoAndActivoTrue(code).orElseThrow(()->ApiException.conflict("Missing required additional master "+code));if(designacionAdicionales.findByDesignacionIdAndAdicionalIdAndVigenteTrue(d.getId(),a.getId()).isPresent())return 0;DesignacionAdicional x=new DesignacionAdicional();x.setDesignacion(d);x.setAdicional(a);x.setValor(new BigDecimal(source.replace(",",".")));x.setObservaciones("Valor crudo: "+source);designacionAdicionales.save(x);audit.recordChange(org,"ADICIONAL_CREADO","DESIGNACION_ADICIONAL",x.getId(),"null","{\"codigo\":\""+code+"\",\"valor\":\""+source+"\"}");return 1;}
 private String personJson(Persona p){if(p==null)return "null";return "{\"dni\":\""+safe(p.getDni())+"\",\"cuil\":\""+safe(p.getCuil())+"\",\"nombres\":\""+safe(p.getNombres())+"\",\"apellido\":\""+safe(p.getApellido())+"\"}";} private String designacionJson(Designacion d){if(d==null)return "null";return "{\"personaId\":"+d.getPersona().getId()+",\"organizacionId\":"+d.getOrganizacion().getId()+",\"sectorId\":"+(d.getSector()==null?"null":d.getSector().getId())+",\"fechaInicio\":\""+d.getFechaInicio()+"\"}";} private String safe(String s){return s==null?"":s.replace("\\","\\\\").replace("\"","\\\"");}
 private boolean validNumber(String s){if(s==null||s.isBlank())return true;try{new BigDecimal(s.replace(",","."));return true;}catch(NumberFormatException e){return false;}} private ImportacionPersonal find(Long id){return imports.findById(id).orElseThrow(()->ApiException.notFound("Personnel importation not found"));} private static class Counts{int newPeople,oldPeople,newDesignations,oldDesignations,masters,invalid,invalidAdditional,duplicates,additional;}
}
